package ru.truetv.bridge.android;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import ru.truetv.bridge.Wire;
import ru.truetv.bridge.SharedText;

/** Share target, not a second file manager. Discovery ends when the chooser leaves the foreground. */
public final class SendActivity extends Activity implements SendService.Listener {
 private final ArrayList<Uri> uris=new ArrayList<>();private final ArrayList<Discovery.Peer> peers=new ArrayList<>();private Discovery discovery;private TextView state;private ListView list;private Button cancel;private ProgressBar progress;private boolean sending,waitingForPrevious,resumed;private String lastStatus,sharedText;
 protected void onCreate(Bundle saved){super.onCreate(saved);requestWindowFeature(Window.FEATURE_NO_TITLE);BridgeUi.top(this);LinearLayout body=BridgeUi.box(this);body.addView(BridgeUi.label(this,"To TV",22));state=BridgeUi.label(this,"",16);body.addView(state);list=new ListView(this);list.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,new ArrayList<String>()));list.setOnItemClickListener((p,v,pos,id)->send(peers.get(pos)));body.addView(list,new LinearLayout.LayoutParams(-1,BridgeUi.dp(this,170)));progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);progress.setVisibility(View.GONE);body.addView(progress,new LinearLayout.LayoutParams(-1,BridgeUi.dp(this,14)));cancel=BridgeUi.button(this,BridgeUi.w(this,"Отменить","Cancel"),()->{SendService s=SendService.active;if(sending&&s!=null&&!s.done)s.cancel();finish();});body.addView(cancel);setContentView(body);
  if(saved!=null&&saved.getBoolean("sending",false)){sending=true;lastStatus=saved.getString("lastStatus");changed();return;}
  if(!Intent.ACTION_SEND.equals(getIntent().getAction())&&!Intent.ACTION_SEND_MULTIPLE.equals(getIntent().getAction())&&SendService.active!=null&&!SendService.active.done){sending=true;changed();return;}if(getIntent().getStringExtra("totv_result")!=null){state.setText(getIntent().getStringExtra("totv_result"));list.setVisibility(View.GONE);return;}Intent intent=getIntent();try{if(Intent.ACTION_SEND_MULTIPLE.equals(intent.getAction())){ArrayList<Uri> incoming=intent.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(incoming!=null)uris.addAll(incoming);}else{Uri single=intent.getParcelableExtra(Intent.EXTRA_STREAM);if(single!=null)uris.add(single);}if(uris.isEmpty()&&intent.getClipData()!=null)for(int n=0;n<intent.getClipData().getItemCount();n++){Uri u=intent.getClipData().getItemAt(n).getUri();if(u!=null&&"content".equals(u.getScheme()))uris.add(u);}if(uris.isEmpty()){CharSequence text=intent.getCharSequenceExtra(Intent.EXTRA_TEXT);if(text==null&&intent.getClipData()!=null&&intent.getClipData().getItemCount()>0)text=intent.getClipData().getItemAt(0).getText();if(text==null)throw new IllegalArgumentException();sharedText=text.toString();SharedText.encode(sharedText);}if(uris.size()>Wire.MAX_FILES)throw new IllegalArgumentException();for(Uri u:uris)if(u==null||!"content".equals(u.getScheme()))throw new IllegalArgumentException();}catch(Exception e){state.setText(e instanceof java.io.IOException?BridgeUi.w(this,"Текст слишком большой или содержит недопустимые символы. Максимум 256 КБ UTF-8.","Text is too large or contains invalid characters. Maximum 256 KB UTF-8."):BridgeUi.w(this,"Выберите файл или текст → Отправить → To TV.","Select a file or text → Share → To TV."));list.setVisibility(View.GONE);return;}

  waitingForPrevious=SendService.active!=null&&!SendService.active.done;
  discovery=new Discovery(this,new Discovery.Listener(){public void peers(List<Discovery.Peer> found){peers.clear();for(Discovery.Peer p:found)if(sharedText==null||p.text)peers.add(p);ArrayAdapter<String> a=(ArrayAdapter<String>)list.getAdapter();a.clear();for(Discovery.Peer p:peers)a.add(p.name+" · "+p.host.getHostAddress());a.notifyDataSetChanged();state.setText((sharedText==null?BridgeUi.w(SendActivity.this,"Файлов: ","Files: ")+uris.size():BridgeUi.w(SendActivity.this,"Текст","Text"))+(peers.isEmpty()?BridgeUi.w(SendActivity.this," · Поиск устройств…"," · Searching for devices…"):BridgeUi.w(SendActivity.this," · Выберите устройство"," · Choose a device")));}public void error(String e){state.setText(BridgeUi.w(SendActivity.this,"Поиск недоступен: ","Discovery unavailable: ")+e);}});state.setText(BridgeUi.w(this,"Поиск устройств в локальной сети… Откройте To TV или окно приёма на нужном устройстве.","Finding devices on the local network… Open To TV or the receive window on the other device."));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},21);
 }
 private void send(Discovery.Peer peer){if(waitingForPrevious||sending)return;Intent i=new Intent(this,SendService.class).putParcelableArrayListExtra("uris",uris).putExtra("host",peer.host.getAddress()).putExtra("scope",peer.host instanceof java.net.Inet6Address?((java.net.Inet6Address)peer.host).getScopeId():0).putExtra("port",peer.port).putExtra("peer",peer.id).putExtra("lan4",peer.lan).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(sharedText!=null)i.putExtra(SharedText.EXTRA,sharedText);else{ClipData clip=ClipData.newRawUri("To TV",uris.get(0));for(int n=1;n<uris.size();n++)clip.addItem(new ClipData.Item(uris.get(n)));i.setClipData(clip);}try{sending=true;if(discovery!=null)discovery.close();list.setVisibility(View.GONE);state.setText(BridgeUi.w(this,"Подключение…","Connecting…"));BridgeUi.start(this,i);}catch(RuntimeException e){sending=false;state.setText(BridgeUi.error(this,e));}}
 public void changed(){SendService s=SendService.active;if(waitingForPrevious){if(s!=null&&!s.done){state.setText(BridgeUi.w(this,"Предыдущая передача ещё выполняется…","Previous transfer is still running…"));list.setVisibility(View.GONE);return;}waitingForPrevious=false;list.setVisibility(View.VISIBLE);if(discovery!=null&&resumed)discovery.start();}if(!sending)return;if(s!=null){lastStatus=s.status;state.setText(s.status);list.setVisibility(View.GONE);progress.setVisibility(s.done?View.GONE:View.VISIBLE);progress.setIndeterminate(s.total<0);if(s.total>=0)progress.setProgress(s.total==0?1000:(int)Math.min(1000,1000d*s.bytes/s.total));cancel.setText(BridgeUi.w(this,s.done?"Закрыть":"Отменить",s.done?"Close":"Cancel"));}else if(sending){progress.setVisibility(View.GONE);cancel.setText(BridgeUi.w(this,"Закрыть","Close"));state.setText(lastStatus==null?BridgeUi.w(this,"Передача завершена. Результат — в уведомлении To TV.","Transfer ended. See the To TV notification."):lastStatus);}}
 protected void onSaveInstanceState(Bundle out){out.putBoolean("sending",sending);out.putString("lastStatus",lastStatus);super.onSaveInstanceState(out);}
 protected void onNewIntent(Intent intent){super.onNewIntent(intent);sending=false;waitingForPrevious=false;setIntent(intent);recreate();}
 protected void onResume(){super.onResume();resumed=true;SendService.observe(this);if(discovery!=null&&!sending&&!waitingForPrevious)discovery.start();}protected void onPause(){resumed=false;SendService.observe(null);if(discovery!=null)discovery.close();super.onPause();}protected void onDestroy(){if(discovery!=null)discovery.close();super.onDestroy();}
}
